/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «هي.. هكذا: كيف نفهم الأشياء من حولنا؟» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["sun2"]={"id":"sun2","title":"هي.. هكذا: كيف نفهم الأشياء من حولنا؟","sub":"الجزء الثاني: 30 سنّة إلهية في الأنفس والمجتمعات","author":"أ.د. عبد الكريم بكار","coauthors":[],"translator":"","publisher":"دار السلام للطباعة والنشر والتوزيع والترجمة، القاهرة (بالاشتراك مع مؤسسة الإسلام اليوم)","year":"1433ه / 2012م","edition":"الطبعة الأولى","series":"هي.. هكذا (الجزء الثاني)","lead":"يعرض الكتاب 30 سنّة ربانية في الأنفس والمجتمعات، لكل منها مفاهيم ونماذج تطبيقية وجواب عن سؤال «كيف نتعامل مع هذه السنّة؟». يقول المؤلف في مقدمته: «إن الهدف النهائي من وراء هذا الكتاب هو توفير أُسس وأُطر لفهم التاريخ والواقع والتنبؤ بالمستقبل في حالة شُحّ المعلومات وفي حالة اضطرابها وتقاطع بعضها مع بعض.» (ص 6)","audience":"الشباب والمربون والمعلمون والمثقفون، والقارئ العام المهتم بفهم الإنسان والمجتمع","bio":"يُعدُّ د. عبد الكريم بن محمد الحسن بكار أحد المؤلفين البارزين في مجالات التربية والفكر الإسلامي؛ حيث يسعى إلى تقديم طرح مُؤصَّل ومُجدِّد لمختلف القضايا ذات العلاقة بالحضارة الإسلامية، وقضايا النهضة والفكر والتربية، والعمل الدعوي.","chapters":[{"k":"c1","t":"الفراغ والإمكانات والوظيفة","q":"كيف يفسر الفراغ والإمكانات والوظيفة قيمة الأشياء؟","essence":"الفراغ يُملأ، والروح تحدها الإمكانات، والقيمة بالوظيفة","kw":["الفراغ","الإمكانات","الوظيفة"],"sections":[{"t":"(1) الطبيعة تكره الفراغ","pg":9,"key":"فطر الله الأشياء على الميل إلى الامتلاء والتناسق والنفور من الفراغ، بوصفه شيئًا يقود إلى العدم أو يوحي به","p":["يحدث الفراغ في كل المجالات والوضعيات والذين يرونه قبل غيرهم هم أهل المجال الذي حدث فيه الفراغ، لكن الذين يبادرون منهم إلى الاستفادة منه هم أهل المبادرة والجرأة والمغامرة المحسوبة."],"items":[{"h":"الوطن قاسم مشترك","x":"ضعف الشعور الوطني فراغ ينشأ حين لا يجذب المشترك الأعظم الناس إليه، «وأشد ما يحطم القاسم المشترك هو التمييز بين المواطنين في الحقوق وفرص العمل؛ لأي سبب من الأسباب.»"},{"h":"فراغ السوق","x":"الفراغ في السوق يعطي ربحًا أعلى، لكنه لا يدوم لأن غيرك سيسارع إلى ملئه."},{"h":"الإنسان متسائل متوجس","x":"حين يغيب العلم يملأ الناس الفراغ بالأساطير وقراءة الكف والفنجان والأبراج."},{"h":"الفراغ فرصة","x":"الشباب يعانون فراغًا فكريًّا وروحيًّا، ومن يقدم لهم البديل الجاد يملأ هذا الفراغ قبل التوافه."}]},{"t":"(2) الروح محدودة بحدود الجسد","pg":17,"key":"أن الروح مهما كانت متوهجة وصادقة ومندفعة، فإن تأثيرها وإنجازاتها ونجاحها يظلُّ إلى حدٍّ مَا خاضعًا لإمكانات الجسد","p":["الروح في شرحنا لهذه السُّنة تتمثل في المعنويات المرتفعة والنوايا الحسنة والغيرة والعزيمة والشجاعة والإقدام والإخلاص","فالنوايا الحسنة والحماسة المشتعلة لا تكفيان لتحقيق النجاح الواضح"],"items":[{"h":"المقصود بالجسد","x":"ما لدينا من قدرات ووسائل وأساليب وممتلكات وخبرات عملية."},{"h":"الأب المحب","x":"أب يحب ابنه المراهق بلا ثقافة تربوية فيرسب الابن: الروح موجودة لكن الإمكانات قاصرة."},{"h":"الوحدة بين شعبين","x":"إذا تفاوت الدخل بين شعبين تفاوتًا كبيرًا رأى الثري الوحدة مصدر إفقار له، فتعجز الروح عن تجاوز حدود الواقع."},{"h":"الروح هي الأساس","x":"الجيش المدجج بالسلاح إذا اعتقد أنه سيهزم فلن تنفعه أسلحته."},{"h":"تعويض نقص الإمكانات","x":"«بالعمل الشاقّ والمثابرة وحسن التخطيط يمكن للإنسان أن يخفف من آثار شُحّ الموارد وضعف الإمكانات.»"}]},{"t":"(12) الشيء بوظيفته","pg":117,"key":"فقيمة الأشياء بالوظائف والأدوار التي تؤدِّيها، وكلما كثرت الوظائف الإيجابية للشيء علتْ قيمته","p":["إن فقدان الوظيفة هو فقدان للذات أو فقدان للوجود","ما دام الشيء بوظائفه، فإن القيام الجيد بالكثير من الوظائف يعني حياة مضاعفة"],"items":[{"h":"تكلفة الوجود","x":"لكل شيء تكلفة وجود، ووظائفه تخففها أو تلغيها، فيكون الغنم في مقابل الغرم."},{"h":"النقود والسلاح","x":"العملة التي يتقلب سعرها تفقد وظيفتها مقياسًا للقيم، والبندقية بلا ذخيرة يصبح الرمح أنفع منها."},{"h":"الجار","x":"«فإذا لم يلمس الجار من جاره شيئًا من ذلك، فإن عدمه خير من وجوده»"},{"h":"الثروة والزواج","x":"الثروة التي لا تؤدي وظيفتها ملكية وهمية، والشراكة الزوجية إذا كفت عن وظائفها كان المتوقع الطلاق."},{"h":"القوة كالنار","x":"«فالقوة مثل النار إذا لم تُستخدم بشكل دقيق وحذر فيما ينبغي أن تُستخدم فيه فإنها تتحوَّل إلى أداة إفساد وتخريب.»"}]}],"quiz":[{"q":"بحسب سنة «الطبيعة تكره الفراغ»، من الأقدر على الإفادة من فراغ يظهر في مجال ما؟","o":["أهل المبادرة والجرأة والمغامرة المحسوبة","أهل المجال الذين رأوا الفراغ قبل غيرهم","أصحاب الخبرة الطويلة والمال الوفير فيه","من يجمع أكبر قدر من المعلومات الدقيقة عنه"],"why":"لكن الذين يبادرون منهم إلى الاستفادة منه هم أهل المبادرة والجرأة والمغامرة المحسوبة.","pg":14},{"q":"أب يحب ابنه المراهق حبًّا صادقًا، لكنه بلا ثقافة تربوية فرسب الابن. كيف يفسر الكتاب ذلك؟","o":["تحقق الروح ظل محدودًا بحدود الإمكانات","حب الأب لابنه كان ضعيفًا في حقيقة أمره","الابن متمرد على كل توجيه يأتيه","قسوة الأب وكثرة تهديده لابنه المراهق"],"why":"إن الروح متوفرة لدى ذلك الأب، وهي حبه لولده والرغبة في تفوقه والسعي إلى ذلك، لكن تحقق الروح ظل محدودًا بحدود الجسد","pg":19},{"q":"متى تصبح ملكيتنا للثروة «وهمية» كما يقرر الكتاب؟","o":["حين لا تؤدي وظيفتها في النفع والإنفاق","حين تُجمع من طرق غير مشروعة أو مشبوهة","حين تكون أقل من حاجة صاحبها وأسرته","حين يخاف صاحبها عليها من الضياع والسرقة"],"why":"فإذا لم تؤدِّ الثروة هذه الوظيفة، فإن ملكيتنا لها تصبح ( وهمية )","pg":120},{"q":"يرى المؤلف أن الروح هي الأساس، فلماذا لا يكتفي بها لتحقيق النجاح؟","o":["لأن النوايا والحماسة وحدها لا تكفي للنجاح","لأن الإمكانات المادية أهم من المعنويات","لأن الحماسة تقود صاحبها دائمًا إلى التهور","لأن الروح العالية لا تدوم إلا أيامًا قليلة"],"why":"فالنوايا الحسنة والحماسة المشتعلة لا تكفيان لتحقيق النجاح الواضح","pg":22},{"q":"رجل كان يدير شركة كبرى، ثم تقاعد فتراجعت أدواره واحدًا بعد آخر حتى سئم الحياة. أي فكرة في الكتاب تفسر حاله؟","o":["فقدان الوظيفة فقدان للذات أو للوجود","الفراغ يملؤه الناس بالخرافة والأساطير","الإنسان متذمر يحن دائمًا إلى ماضيه","المبالغة في الراحة مكمن مقتلها"],"why":"إن فقدان الوظيفة هو فقدان للذات أو فقدان للوجود","pg":118}]},{"k":"c2","t":"الشيء في محيطه ونظامه","q":"لماذا لا يُفهم الشيء ولا يعمل بمعزل عن محيطه؟","essence":"كل شيء جزء من محيط يمنحه معناه","kw":["المحيط","الانفتاح","النظم المفتوحة"],"sections":[{"t":"(3) يكتسب الشيء دلالته من محيطه","pg":25,"key":"إن كل ما يبدو لنا معزولًا هو في الحقيقة جزء من شيء آخر","p":["لكلِّ شيء وجودان: وجود ذاتي ووجود علاقاتي","فالشيء كثيرًا ما يكون ابن علاقاته."],"items":[{"h":"قصور اللغة","x":"اللغات كلها تعاني القصور الذاتي، ولهذا قيل: «لا تسأل عن معنى الكلمة، ولكن سلْ عن استعمالها»."},{"h":"الخرزة في العقد","x":"نفهم الشيء بموقعه بين ما قبله وما بعده، كتقدير «جيد» بين «مقبول» و«ممتاز»."},{"h":"التناسق","x":"«التناسق هو أهم معيار من معايير الجمال»، فالعين الواسعة جدًّا في وجه صغير لا تكون جميلة."},{"h":"العطايا والمصائب","x":"يتأثر وقع العطاء والمصيبة في النفس بما يناله الآخرون أو يصيبهم."},{"h":"كيف نتعامل","x":"نستعمل اللغة الكمية بدل الوصفية، ونهتم بالبيئة: «فالأفضل هو توفير البيئة التي تساعدهم على أن يكونوا صالحين ومنتجين ومتعاونين»"}]},{"t":"(6) الانفتاح طريق التكامل","pg":55,"key":"فإن لنا أن نقول: إنه لا تكامل من غير انفتاح، لكن ليس كل انفتاح يُنتج التكامل.","p":["الانفتاح الجيد هو الذي يمكّننا من الحفاظ على جوهر ما لدينا مع مساعدتنا على إنعاشه وإثرائه ونقده وتطويره.","التربية تفاعل حقيقي بين المربي والمتربي"],"items":[{"h":"التكامل مع الآخرين","x":"نحتاج إلى غيرنا ليرينا عيوبنا، «فالمرء لا يرى إلا جزءًا من عيوبه»."},{"h":"المربي والمتربي","x":"المتربي مهما تمرد نتاج علاقته بأسرته ومجتمعه، والمربي نفسه يتعلم من تربيته."},{"h":"الزوجان","x":"«التنوع في إطار الوحدة»، والتكامل بينهما مبني على الاختلاف لا على التشابه."},{"h":"من التنافس إلى التكامل","x":"نجد سبيل التكامل حتى مع الخصوم إذا أدركنا أن لدينا مشكلات حلولها عند غيرنا."},{"h":"خطر الانغلاق","x":"«البيئات المغلقة هي بيئات مثالية للانحراف والتفسخ»"}]},{"t":"(17) كل نظام هو جزء من كلٍّ أكبر","pg":169,"key":"لدينا حقيقة مهمة جدًّا، هي أن النظم لا تعمل في فراغ، أي إن البيئة التي يعمل فيها النظام تحسِّن من كفاءته وجدواه، أو تعمل على ما يخفِّضها","p":["« إنه ذلك المجموع الذي يعمل في الوجود بوصفه شيئًا كليًّا مكونًا من أجزاء تتبادل فيما بينها الاعتماد والتفاعل »","كلما كان النظام أشد انغلاقًا كان اتجاهه نحو الفناء أوْكد."],"items":[{"h":"نظم مغلقة ومفتوحة","x":"الساعة نموذج للنظام المغلق، والمغلق تمامًا نادر، وكل الأنشطة الإنسانية تتم في نظم مفتوحة."},{"h":"استعارة النظم","x":"استعرنا نظمًا كثيرة فلم تؤت ثمارها لاختلاف بيئاتنا عن بيئاتها."},{"h":"مصنع السجاد","x":"مصنع ناجح التخطيط قد يتعثر لأن عناصر بيئته من منافسة وأجور وأذواق خارجة عن سيطرته."},{"h":"نظام الزكاة","x":"جزء من النظام الاقتصادي الأوسع، ولا تظهر كفاءته إلا مع كفاءة باقي النظم."},{"h":"النظام التعليمي","x":"يتكون من نظم القبول والتدريس والاختبارات والتعاون مع الأسر، وهو جزء من منظومة أوسع."},{"h":"استيراد نظام","x":"لا نستورد نظامًا إلا بعد التأكد من أننا نملك الظروف التي أحاطت به عند أهله."}]},{"t":"(27) المبادئ لا تعمل في فراغ","pg":275,"key":"ومن هنا فإن التزام أي واحد بأي مبدأ يؤمن به هو التزام نسبي ومنقوص، وهذا يعني فعلًا أن للظروف المحيطة قدرًا كبيرًا من التأثير في الالتزام بالمبادئ","p":["فتعشُّق الحرية ليس كافيًا ليعيش الناس أحرارًا، إن الحرية في جوهرها هي القدرة على الاختيار"],"items":[{"h":"الأعراف عقد غير مكتوب","x":"في كل مجتمع أعراف وتقاليد تتحكم بالسلوك، وتلقى أحيانًا من المراعاة أكثر مما تلقاه الشرائع."},{"h":"العقيدة العملية","x":"يؤمن الناس بالمبادئ، لكن ما يظنونه مصالح يصنع لهم في الحياة العملية عقيدة أخرى."},{"h":"العدل","x":"حب العدل لا يكفي لإشاعته، فهو يحتاج إلى قضاء مستقل وفعال وإعلام حر وثقافة حقوقية."},{"h":"حسن الجوار","x":"يتفاوت تجسيده بسعة البيئة وضيقها والوضع الحضاري ومستوى التعليم."},{"h":"القدوة","x":"لا يتغير تصور الناس لصعوبة الفضيلة «إلا من خلال رؤية نماذج حيَّة يتجسَّد في سلوكها ما تدعوهم إليه»"}]}],"quiz":[{"q":"ما المقصود بقول المؤلف إن لكل شيء «وجودين»؟","o":["وجود ذاتي ووجود علاقاتي","وجود مادي ووجود معنوي روحي","وجود ظاهر ووجود خفي باطن","وجود دائم ووجود عارض مؤقت"],"why":"لكلِّ شيء وجودان: وجود ذاتي ووجود علاقاتي","pg":27},{"q":"متى يكون الانفتاح على الآخرين جيدًا بحسب الكتاب؟","o":["حين يحفظ جوهرنا ويعيننا على إثرائه وتطويره","حين نأخذ من الآخرين كل ما لديهم دون نقد","حين نكتفي بما عندنا ونتجنب الاحتكاك بغيرنا","حين نتبنى أفكار الأقوى لأنه الأنجح دائمًا وأبدًا"],"why":"الانفتاح الجيد هو الذي يمكّننا من الحفاظ على جوهر ما لدينا مع مساعدتنا على إنعاشه وإثرائه ونقده وتطويره.","pg":61},{"q":"استوردت دولة نظامًا ناجحًا في بلد متقدم، فلم يؤت ثماره عندها. ما التفسير الأقرب لما يقرره الكتاب؟","o":["اختلاف بيئتنا عن البيئة التي نشأ فيها النظام","خلل في تصميم النظام نفسه منذ لحظة نشأته الأولى","قلة المال المرصود لتطبيقه على أرض الواقع","رفض الناس لكل نظام جديد يأتيهم من الخارج"],"why":"وقد استعرنا الكثير من النظم في الكثير من المجالات، ولم تؤتِ الثمار التي كنَّا نتوقعها منها بسبب اختلاف بيئاتنا عن البيئات التي نشأت فيها تلك النظم.","pg":172},{"q":"ما الهدف من فريضة الزكاة كما يقرره المؤلف؟","o":["تطهير نفوس المزكين وتقوية روح التعاون","القضاء التام على الفقر في المجتمع كله","تمويل الدولة ومشروعاتها الاقتصادية","إزالة الفوارق حتى تتساوى الثروات"],"why":"وإنما الهدف من فريضة الزكاة هو تطهير نفوس وأموال المزكين وتقوية الروح التعاونية لدى المسلمين","pg":173},{"q":"أم تؤمن بالصدق، لكن ابنها غاب يومًا وسيُحرم بسببه من سنة دراسية، فاختلقت له عذرًا. ماذا يسمي المؤلف ما يحكم سلوك كثير من الناس في مثل هذا؟","o":["العقيدة العملية التي تصنعها المصالح","الحيل الدفاعية التي تعمل لا شعوريًّا","التسامي الذي يرفع السلوك إلى المقبول","الضغط الاجتماعي الذي يشوه الفطرة"],"why":"إن الناس يحملون بين جوانحهم إيمانًا عميقًا بكثير من المبادئ والقيم العظيمة، لكنهم في الحياة العملية، ومما يظنونه مصالح لهم عقيدة جديدة، يمكن أن نسميها ( العقيدة الاجتماعية ) أو ( العقيدة العملية )","pg":279}]},{"k":"c3","t":"التوازن والمبالغة والتطرف","q":"لماذا يصعب التوازن، وما عاقبة المبالغة والتطرف؟","essence":"التوازن نسبي، والمبالغة تقتل، والتطرف يستدعي مثله","kw":["التوازن","المبالغة","التطرف"],"sections":[{"t":"(7) التوازن مسألة تستعصي على الحسم","pg":65,"key":"الموقف المتوازن هو ذلك الموقف الذي يدرك فيه الإنسان على نحوٍ جيد أهدافه وحاجاته وواجباته وإمكاناته والظروف المحيطة به، والمعوقات والعقبات التي قد تواجهه.. ثم يقوم بالتحرك وفق ذلك الإدراك على مقدار الوسع والطاقة.","p":["والمشكل الأساسي هو أن ( العقل ) البشري لا يملك المهارة المطلوبة لفهم ما هو من قبيل الصفات والكيوف","فإن إدخال الأشياء البعيدة جدًّا في الموازنات والأولويات يعقِّد الأمور، ويجعل ما نسمِّيه توازنًا أقرب إلى الوهم والتخبُّط."],"items":[{"h":"سلمان وأبو الدرداء","x":"«فأعطِ كلَّ ذي حقٍّ حقَّه»، وقال النبي: «صدق سلمان»."},{"h":"الموازنات والأولويات","x":"فقه الأولويات مبني على فقه الموازنات، وكلاهما لا يكتمل."},{"h":"صعوبات متفاوتة","x":"تزداد صعوبة التوازن بكبر حجم القضية وطول المدة الزمنية التي ننظر إليها."},{"h":"فهم الواقع","x":"نتثبت من المعلومات، ونلتزم الموضوعية، ونتجنب القطع في توصيف الواقع «لأنه في الحقيقة لا يرى سوى جزء منه.»"},{"h":"التسامح مع الناقدين","x":"كل مواقفنا توازنات ناقصة، «وهذا يتطلَّب مِنّا تفهُّم مواقف الناقدين والمعترضين وإظهار نوع من التسامح تجاههم»"},{"h":"التوازن يتغير","x":"المدين يقتر حتى يقضي دينه، فإذا قضاه صار التقتير غير مقبول لتغير المعطيات."}]},{"t":"(8) المبالغة في الشيء مكمن مقتله","pg":77,"key":"إن ميزات القوة تظلُّ موجودة ما دامت باقية ضمن حدودها، أما إعجازها فيكمن في ملامسة الحد الأقصى لمجالاتها دون تجاوز ذلك الحد.","p":["للأشياء منفعة حَدِّية، وحين يتجاوز شيءٌ ما حدود منفعته، فإنه يصير إلى التلاشي","التربية المثالية هي التي تنطوي على أقل قدر ممكن من التهديد والعقاب والقسوة"],"items":[{"h":"المزاحمة","x":"المبالغة في شيء تزاحم أجزاء المنظومة الأخرى، كمن يسرف في النوم أو اللهو."},{"h":"التهديد","x":"التهديد المبالغ فيه يدرك الطفل أنه لن يُنفذ فيفقد أثره."},{"h":"الرفاهية","x":"الإفراط في المتع يقصر الحياة، والاعتدال يطيلها."},{"h":"المديح","x":"«إذ من المعروف أن التطرف في مديح شخص مَا يؤدِّي إلى استحضار نقائصه وعيوبه»"},{"h":"المزاح","x":"«لكن المزاح النافع والمقبول يفقد فائدته ومشروعيته حين يتجاوز الخطوط الحمراء»"},{"h":"العلاج","x":"«الجهل بالعواقب من أكثر الأسباب المؤدِّية إلى انتشار ( المبالغة )»، فالتوعية واعتدال الأبوين هما البداية."}]},{"t":"(20) التطرف يقود إلى التطرف","pg":199,"key":"إنه ليس التطرف وحده هو الذي يقود إلى التطرف، العنف يقود إلى العنف، والرفق يقود إلى الرفق، واللِّين يقود إلى اللين","p":["وأظن أن التطرف الفكري هو أساس كل تطرف؛ لأن الفكر هو دليل السلوك"],"items":[{"h":"الاعتدال مكتسب","x":"النزوع إلى التطرف قريب من الطبع، والاعتدال يحتاج إلى تعلم وتدريب ومجاهدة للنفس."},{"h":"غموض الاعتدال","x":"يقابل الناس التطرف بمثله لأن حدود الرد المعتدل غائبة عن وعيهم."},{"h":"تدمير الأرضية المشتركة","x":"المتطرف الأول يهدم ما يجمع الطرفين من أعراف ومواثيق فيستدعي ردًّا أشد."},{"h":"ركائز التطرف الفكري","x":"ضآلة الحصيلة العلمية، والتعلق بفكرة ومنع مناقشتها، والتصلب الذهني، والاعتداد المبالغ فيه ببعض المقولات."},{"h":"العلاج","x":"العمل بالحكم الشرعي، والعفو، وتعزيز الروابط المشتركة، وخفض التوتر، والحوار، ونشر الوسطية بالقدوة."}]}],"quiz":[{"q":"لماذا يستعصي التوازن على الحسم في رأي المؤلف؟","o":["لأن العقل لا يحسن فهم الصفات والكيوف","لأن الناس لا يرغبون في الاعتدال أصلًا","لأن الشريعة لم تضع قواعد للموازنات","لأن المعلومات عن الواقع منعدمة تمامًا"],"why":"والمشكل الأساسي هو أن ( العقل ) البشري لا يملك المهارة المطلوبة لفهم ما هو من قبيل الصفات والكيوف","pg":67},{"q":"أب يهدد طفله دائمًا بعقوبات قاسية لا ينفذها. ما الذي يقرره الكتاب في مثل هذا الأسلوب؟","o":["أن التربية المثلى أقلها تهديدًا وعقابًا وقسوة","أن التهديد الشديد يضمن طاعة الطفل مدة طويلة جدًّا","أن الطفل لا يفهم في صغره إلا لغة الوعيد","أن الوعيد مقبول ما دام لحماية الطفل من الخطر"],"why":"التربية المثالية هي التي تنطوي على أقل قدر ممكن من التهديد والعقاب والقسوة","pg":79},{"q":"ما الذي يؤدي إليه الإفراط في مديح شخص بحسب الكتاب؟","o":["استحضار نقائصه وعيوبه","زيادة محبة الناس له وثقتهم","تحفيزه على مزيد من الإتقان","رفع مكانته عند خصومه"],"why":"إذ من المعروف أن التطرف في مديح شخص مَا يؤدِّي إلى استحضار نقائصه وعيوبه","pg":81},{"q":"أي أقسام التطرف يراه المؤلف أساسًا لغيره؟","o":["التطرف الفكري","التطرف الشعوري","التطرف السلوكي","التطرف في الترف"],"why":"وأظن أن التطرف الفكري هو أساس كل تطرف؛ لأن الفكر هو دليل السلوك","pg":203},{"q":"اشتد الخلاف بين جهتين وهبت بينهما رياح حرب باردة. بماذا يبدأ الكتاب في العلاج؟","o":["خفض التوتر بإيقاف الحملات الإعلامية","الرد بمثل ما فعله الخصم حتى يرتدع","قطع كل صلة بالطرف الآخر حتى يعتذر ويتراجع","حشد الأنصار لإثبات أن الحق معنا وحدنا"],"why":"الأول: هو خفض التوتر، وذلك من خلال إيقاف الحملات الإعلامية وما فيها من اتهامات وحط من شأن الخصم.","pg":206}],"scene":{"t":"مزاح يتجاوز الحد","x":"معلم يلاحظ أن طالبًا يمازح زميله أمام الصف مزاحًا يجرحه ويضحك منه الآخرون.","opts":["يوقف المزاح عند حده ويبين أن للمزاح المقبول خطوطًا لا يتجاوزها","يترك المزاح يستمر لأنه يقوي العلاقة بين الطلاب","يمنع كل مزاح في الصف منعًا تامًّا"],"why":"لكن المزاح النافع والمقبول يفقد فائدته ومشروعيته حين يتجاوز الخطوط الحمراء","pg":82}},{"k":"c4","t":"الغموض والنسبية والتلاعب بالألفاظ","q":"كيف يربك الغموض والنسبية وتلاعب الألفاظ فهمنا؟","essence":"الوضوح فضيلة، والنسبي غير المطلق، والألفاظ قد تخدع","kw":["الغموض","النسبية","التسمية"],"sections":[{"t":"(9) الفوضى موصولة بالغموض","pg":85,"key":"ومع الغموض تأتي الفوضى؛ حيث يصبح الإمساك برؤوس الموضوعات وتحرير بعض المسلَّمات أمرًا صعبًا","p":["علينا أن ننظر إلى الوضوح في كل شيء على أنه فضيلة من أعظم الفضائل","اعتماد التوصيف أساسًا في محاربة الغموض والفوضى"],"items":[{"h":"المؤسسات بلا توصيف","x":"«إن هناك الكثير من المؤسسات الصغيرة التي تعاني من الافتقار إلى التوصيف الذي أشرنا إليه؛ ولذلك فإنها تكون غارقة في الفوضى والنزاعات والاتهامات المتبادلة مع انخفاض الإنتاجية.»"},{"h":"غموض الكلمات","x":"ألفاظ مثل الأمن والحرية والثقافة كثيرة التعريفات، فيكثر الجدل حولها."},{"h":"غموض الأشخاص","x":"من يتكتم على كل شيء «يجعل من نفسه محورًا لظنون الناس وشكوكهم وتقوّلاتهم»."},{"h":"الحدود الفاصلة","x":"خطوط فرش المسجد الضيقة جعلت الصفوف غير مستوية، وغموض حدود الأراضي أثار النزاعات."},{"h":"كيف نتعامل","x":"نحدد المصطلحات، ونسأل من نشرح له عما فهم، ونفتت القضايا الكبرى، ونستعمل الأرقام بدل الأوصاف."}]},{"t":"(11) كل ما هو إنساني نسبي","pg":107,"key":"إن الإنسان ضعيف، وقدراته محدودة، وحصوله على الكمال لا يتجاوز المقاربة والمناهزة، ولهذا فإن كل ما لديه من صفات حسنة وقبيحة نسبيّ في حسنه وقبحه","p":["فأنا لا أقول: كل شيء نسبي، فهذا غير صحيح في نظري بسبب كثرة المطلقات التي نؤمن بها","حين نذهب باتجاه تصور الأصول والكليات والقواعد الكبرى، فإننا نتجه في الحقيقة نحو المُطلَقات، وحين نتحدث عن الجزئيات والفرعيات والمسائل والملاحظات الصغيرة، فإننا نتحدث آنذاك عن أمور نسبية"],"items":[{"h":"خطر تنسيب القيم","x":"من يسوغ الكذب أو الغش بظروفه يُخرج القيم من حيز الإطلاق، «وهو يشكل مقتلًا خطيرًا للقيم النبيلة ومنزلقًا مخيفًا نحو الوقوع في المحظورات!»"},{"h":"مصادر النسبية","x":"اختلاف الثقافات الشعبية، والظروف المحيطة، ومعايير التقييم، وكون الفضيلة وسطًا بين رذيلتين."},{"h":"لا كمال للإنسان","x":"معرفة المرء أنه لن يبلغ الكمال تحميه من إرهاق نفسه وغيره."},{"h":"حماية من الغرور","x":"«الاعتقاد بنسبية نجاحاتنا يحمينا من الغرور والكبر»، ويجعلنا نتقبل النقد والنصح."}]},{"t":"(22) تسمية الأشياء بغير أسمائها آخر الحيل","pg":219,"key":"إن أغلب الباحثين المعنيين بمسألة ( المعنى ) اليوم لا يشكّون في أن اللغة كما تكون وسيلة للفهم والإفهام هي في الوقت نفسه وسيلة ممتازة لسوء الفهم وقطع التفاهم وحجب المعنى","p":["الناس يسمُّون الأشياء بغير اسمها حين تضيق عليهم سبل الحيل","فالإنسان الحديث يملك من مهارة التلاعب بالألفاظ أكثر بكثير مما يملكه من يقظة الضمير وقوة الأخلاق."],"items":[{"h":"حديث الخمر","x":"«لا تذهب الليالي والأيام حتى تشرب فيها طائفة من أمتي الخمر يسمُّونها بغير اسمها»."},{"h":"من شواهد العصر","x":"تسمية الرشوة هدية أو إكرامية، والتفلت تفتحًا، والملتزم متشددًا، والعدوان تصعيدًا."},{"h":"تجميل الحقيقة المرة","x":"يسعى الناس دائمًا إلى جعل وقع الحقيقة المرة في النفوس ضئيلًا قدر الإمكان."},{"h":"متى تكون التسمية بالأسماء أصلًا","x":"حين تكون الثقافة منفتحة متسامحة ويسود العدل والحرية."},{"h":"واجب المثقف","x":"أن يضع النقاط على الحروف، وإن عجز عن التسمية الصحيحة فلا يسمي الشيء بعكس اسمه، مع اعتدال النبرة والاحتراز."}]}],"quiz":[{"q":"مؤسسة صغيرة تكثر فيها النزاعات والاتهامات وتنخفض إنتاجيتها. ما العلاج الذي يقترحه الكتاب؟","o":["اعتماد توصيف واضح للمهام والمسؤوليات","تشديد الرقابة على الموظفين ومعاقبة المخطئ","تغيير المدير واختيار شخص أكثر حزمًا","رفع الرواتب والحوافز حتى يرضى الجميع"],"why":"إن هناك الكثير من المؤسسات الصغيرة التي تعاني من الافتقار إلى التوصيف الذي أشرنا إليه؛ ولذلك فإنها تكون غارقة في الفوضى والنزاعات والاتهامات المتبادلة مع انخفاض الإنتاجية.","pg":88},{"q":"أين تكون الأمور مطلقة وأين تكون نسبية في رأي المؤلف؟","o":["الأصول والكليات مطلقة، والجزئيات نسبية","كل شيء نسبي بلا استثناء في كل مجال","الجزئيات مطلقة، والأصول والكليات نسبية","القيم كلها نسبية تتغير بتغير الظروف"],"why":"حين نذهب باتجاه تصور الأصول والكليات والقواعد الكبرى، فإننا نتجه في الحقيقة نحو المُطلَقات، وحين نتحدث عن الجزئيات والفرعيات والمسائل والملاحظات الصغيرة، فإننا نتحدث آنذاك عن أمور نسبية","pg":109},{"q":"طالب يقول: سمحت لنفسي أن أغش لأن رسوبي كارثة على أسرتي. بم يصف المؤلف هذا اللون من التفكير؟","o":["مقتل خطير للقيم ومنزلق نحو المحظورات","فهم صحيح لنسبية الظروف الإنسانية","ضرورة تبيح المحظور في كل الأحوال","اجتهاد مقبول ما دام الدافع إليه بر الأسرة"],"why":"هذا اللون من الإدراك ومن التفكير يُخرج القيم في كثير من الأحيان من حيز الإطلاق، ويُدخلها في حيِّز النسبية، وهو يشكل مقتلًا خطيرًا للقيم النبيلة ومنزلقًا مخيفًا نحو الوقوع في المحظورات!","pg":110},{"q":"ما الغرض من تسمية المحرم باسم آخر، كتسمية الخمر بالأشربة الروحية؟","o":["التخلص من الدلالات المرتبطة به ومن حكمه","سد نقص حقيقي في ألفاظ اللغة العربية","أن الأسماء القديمة لم تعد مفهومة عندهم","الرغبة في مواكبة لغة العصر وألفاظه الحديثة"],"why":"من الواضح أن التغيير في الاسم يستهدف التخلص من الدلالات والمعاني المرتبطة بالخمر، والتخلص إن أمكن من حكمها، وهو التحريم.","pg":222},{"q":"متى تصبح تسمية الأشياء بأسمائها هي الأصل في مجتمع ما؟","o":["حين تنفتح الثقافة ويسود العدل والحرية","حين يكثر المثقفون والدعاة في المجتمع","حين تشتد الحروب والشدائد الخانقة","حين تزيد الرقابة الرسمية على وسائل الإعلام"],"why":"حين تكون الثقافة السائدة منفتحة ومتسامحة، وحين تسود البلادَ حالةٌ جيدة من العدل والحرية فإن تسمية الأشياء بأسمائها تصبح هي الأصل","pg":225}]},{"k":"c5","t":"المعرفة وفهم الإنسان","q":"كيف نعرف الأشياء والناس معرفة تحسن تعاملنا معهم؟","essence":"العلم بالشيء طريق التعامل الراشد معه","kw":["المقارنة","الجهل المركب","تعقيد الشأن الإنساني"],"sections":[{"t":"(19) الإنسان كائن مقارن","pg":189,"key":"المقارنة أُمُّها الاختلاف، وأبوها الغموض","p":["إن المقارنة هي بنت الاختلاف، وبما أن الاختلاف يشكل طابعًا عامًّا للبشرية فمن الطبيعي أن نجدها في كلِّ مكان.","لنحذر من المقارنة السلبية بين الأبناء وزملاء العمل والأقرباء والأصدقاء، فهذه تبذر العداوة بينهم"],"items":[{"h":"الصغار يقارنون","x":"الطفلة تسأل أمها: ألست أجمل من فلانة؟ والصغار يملكون أصول المقارنة."},{"h":"المقارنة في القرآن والسنة","x":"«فاعتبروا يا أولي الأبصار»، و«انظروا إلى من هو أسفل منكم» في أمور الدنيا، وإلى من هو فوقنا في الخير."},{"h":"الخصوصية","x":"«إنه لا خصوصية من غير الاعتراف بشيء عامّ يُبرزها، ويجعل لها معنى»"},{"h":"إرشادات المقارنة","x":"نتائجها ظنية، والموضوعية فيها تقوم على «البعد عن الظن، والبعد عن الهوى»، وتحتاج شجاعة أدبية ورغبة في الاستفادة."},{"h":"الفوارق والمعنويات","x":"نراعي فوارق السن والظروف، ولا نهمل العناصر المعنوية لحساب المادية."}]},{"t":"(24) نقص العلم بالشيء مفضٍ لسوء التعامل معه","pg":239,"key":"العلم بالشيء هو الطريق القويم للتعامل الراشد معه، والجهل به لا يمكن إلا أن يقود إلى سوء التعامل معه","p":["وَهْمُ المعرفة هو الذي يجعل الناس غارقين في الجهل"],"items":[{"h":"بسيط ومركب","x":"الجهل البسيط أن يجهل المرء ويعلم أنه يجهل، والمركب «أن لا يعرف أنه لا يعرف، ولهذا كانت ( لا أعلم ) نصف العلم»."},{"h":"المعرفة الناقصة","x":"كل شيء وجوده الناقص أفضل من عدمه إلا العلم بالشيء."},{"h":"خصائص الأشياء","x":"بركة سباحة فسد ماؤها لأن صاحبها لم يسأل، «لكن مشكلة الناس غالبًا ما تكون في ظنِّهم أنهم يعرفون كل شيء، ولهذا فإنهم لا يتعلمون، ولا يسألون!»"},{"h":"العلاقة بالآخر","x":"يرى المؤلف أن ضعفنا الموروث هو الذي يغري الآخرين بنا، وأن نصيبنا من أسباب تخلفنا هو الأكبر."},{"h":"تربية الأبناء","x":"«ومعقد نجاح التربية يكمن في الفهم الدقيق لما نريده من الطفل، وما يريده منَّا، والعمل وفق ذلك الفهم.»"},{"h":"التريث في العلاقات","x":"كلما كانت العلاقة أوثق كالزواج والشراكة وجب جمع معلومات أكثر والتريث في عقدها."}]},{"t":"(28) معالجة الشأن الإنساني دائمًا معقدة","pg":287,"key":"كما أن كلَّ إنسانٍ يُشكِّل ظاهرة فريدة، أو هو أشبه بمخطوطة يتيمة لكتاب نفيس","p":["يجب من البداية أن نرضى بفهم ناقص للظواهر الإنسانية، ونرضى بموضوعية غير كاملة في كلِّ أحكامنا على سلوك البشر، وهذا يجعلنا نتواضع"],"items":[{"h":"قوانين تقريبية","x":"«أما في مجال العلوم الإنسانية، فالقوانين والقواعد التي نتوصل إليها تتَّسم بالتقريبية والاحتمالية»"},{"h":"الفرادة","x":"الفرادة سر صعوبة تقنين الشأن الإنساني وسر تعقيده."},{"h":"نظم مفتوحة","x":"كل أنشطتنا تتم في نظم مفتوحة، فخططنا غير مضمونة النتائج."},{"h":"العلاقات أصعب علاجًا","x":"علاج الأمراض البدنية والمشكلات التقنية أسهل من تغيير القناعات وإصلاح العلاقات المتداعية."},{"h":"تفكيك الظاهرة","x":"نقسم الظاهرة كتخلف التعليم إلى وحدات صغيرة: النظم والمناهج والإدارات ودعم الأهالي وسوق العمل، ثم ندمج النتائج."}]}],"quiz":[{"q":"ما الجهل المركب كما يعرفه الكتاب؟","o":["أن لا يعرف المرء أنه لا يعرف","أن يجهل المرء الطريق إلى بيت صديقه","أن يعرف الشيء معرفة ناقصة مشوهة","أن يجهل الأسباب والنتائج معًا"],"why":"والجهل المركب أن لا يعرف أنه لا يعرف، ولهذا كانت ( لا أعلم ) نصف العلم","pg":241},{"q":"معلم يقول لطالب أمام زملائه: لماذا لا تكون مثل أخيك؟ ماذا يقرر الكتاب في مثل هذا السلوك؟","o":["المقارنة السلبية بين الأبناء تبذر العداوة","المقارنة تحفز الطالب على التفوق دائمًا وأبدًا","المقارنة مفيدة إذا كانت أمام الجميع","المقارنة لا أثر لها في نفوس الصغار والكبار"],"why":"لنحذر من المقارنة السلبية بين الأبناء وزملاء العمل والأقرباء والأصدقاء، فهذه تبذر العداوة بينهم","pg":195},{"q":"لماذا يقع كثير من الناس في أخطاء يمكن تجنبها مع توفر المعلومات حولهم؟","o":["لظنهم أنهم يعرفون كل شيء فلا يسألون","لأن المعلومات الصحيحة غير متاحة أبدًا","لأن أهل الاختصاص يكتمون معارفهم","لأن الأخطاء قدر لا يمكن تجنبه"],"why":"لكن مشكلة الناس غالبًا ما تكون في ظنِّهم أنهم يعرفون كل شيء، ولهذا فإنهم لا يتعلمون، ولا يسألون!","pg":244},{"q":"أراد باحث فهم ظاهرة تخلف التعليم في بلده. ما المنهج الذي يقترحه الكتاب؟","o":["تقسيمها إلى وحدات صغيرة ثم دمج النتائج","البحث عن سبب واحد رئيس ومعالجته","مقارنتها بأفضل نظام تعليمي ونقله كما هو","الاكتفاء بآراء المعلمين لأنهم أعلم بها"],"why":"ومن هنا فإن علينا حين نريد فهم ظاهرة إنسانية معينة أن نقسمها إلى أصغر وحدات ممكنة","pg":293},{"q":"لماذا كانت قوانين العلوم الإنسانية أقل صرامة من قوانين الفيزياء والكيمياء؟","o":["لأن كل إنسان ظاهرة فريدة لا تشبه غيرها","لأن علماء الإنسانيات أقل كفاءة من غيرهم","لأن الظواهر الإنسانية لا تخضع لأي سنن","لأن مناهج البحث فيها حديثة النشأة"],"why":"أما في مجال العلوم الإنسانية، فالقوانين والقواعد التي نتوصل إليها تتَّسم بالتقريبية والاحتمالية","pg":289}],"scene":{"t":"مقارنة ظالمة في الحفظ","x":"ولي أمر يشكو للمعلم أن ابنه ذا الست سنوات حفظ جزأين فقط في السنة، بينما حفظ ابن عمه ذو العشر سنوات خمسة أجزاء.","opts":["يبين له أن المقارنة يجب أن تراعي فارق السن، وأن ابنه متفوق قياسًا بعمره","يوافقه ويطلب منه الضغط على ابنه ليلحق بابن عمه","ينصحه بإيقاف الحفظ حتى يكبر الابن"],"why":"فابن السادسة حين يحفظ جزأين في السَّنَة يُعدُّ متفوقًا على ابن العاشرة إذا حفظ خمسة أجزاء، وذلك بسبب فارق السِّن.","pg":195}},{"k":"c6","t":"طبائع في النفس: التذمر والتكيف والتقليد","q":"ما الطبائع التي فُطر عليها الإنسان، وكيف يحسن توجيهها؟","essence":"الإنسان يشكو ويتكيف ويقلد، والوعي يوجه ذلك","kw":["التذمر","التكيف","التقليد"],"sections":[{"t":"(5) الإنسان كائن متذمر","pg":45,"key":"إن شيئًا من التذمر ضروري جدًا لتوازن الشخصية واستقامة الحياة العامة، والتذمر من هذه الناحية يشبه ( القلق ) قليلُه نافع، وكثيره ضار.","p":["التذمر عبارة عن انزعاج داخلي بسبب شعور الإنسان بوجود تصرفات أو أشياء لا تُرضيه","من المهم أن تتذكر أن الشكوى من الشيء تشكل بداية جيدة للعمل على إصلاحه، كما يفعل المريض حين يشكو من ألم في معدته"],"items":[{"h":"الحنين إلى الماضي","x":"يشكو الناس من حاضرهم، فإذا صار تاريخًا حنوا إليه."},{"h":"أسباب ارتفاع الشكوى","x":"البيئة، ف«الشكوى تكون في بعض الأحيان ثقافة عامة يتلقفها الصغار من الكبار»، والعاطفة الزائدة، والانطواء، والمقارنة بالمترفين."},{"h":"الشكوى للتعمية","x":"قد يشكو المرتشي من الرشوة، «وهكذا تصبح الشكوى وسيلة خفية للتعمية والدفاع عن الذات بطريقة غير مباشرة.»"},{"h":"كيف نتعامل","x":"نرحب بالشاكي، ونفرق بين المصيبة والقضاء والقدر، ونتذكر أن الحلول لا تكون كاملة في وسط غير كامل."},{"h":"عند العجز","x":"«وإذا كنا عاجزين تمامًا عن الإصلاح فالإقلال من الشكوى يكون هو الموقف الحكيم.»"}]},{"t":"(16) الإنسان كائن متكيف","pg":157,"key":"التكيف هو عملية مواءمة الإنسان لنفسه مع الأوضاع والظروف الجديدة، وهذه المواءمة تكون في بعض الأحيان بتغيير وضعية الإنسان وتعديل سلوكه، وأحيانًا تكون بتغيير البيئة التي يعيش فيها","p":["فإن المرء كلما كان أقوى عزيمة وأفضل تعليمًا ومتمكنًا ماليًّا أكثر كان التكيف عليه أسهل","التعلم واكتساب المهارات: هذا الأسلوب في التكيف مع الظروف الصعبة من أفضل الأساليب"],"items":[{"h":"أهداف التكيف","x":"البقاء، ثم السعادة والرفاهية، ثم تهيئة البيئة للأداء المتميز."},{"h":"قسما التكيف","x":"تكيف هبة من الله يتم بلا إرادة كتعرق الجسد، وتكيف واع بالإرادة والجهد وهو الأهم."},{"h":"الذكاء والتكيف","x":"«فإن التكيف الاجتماعي الناجح يعبِّر عن ذكاء اجتماعي وعن سواء نفسي جيد»"},{"h":"وسائل التكيف","x":"القدوة الحسنة، ووضع المصيبة في حجمها، واليقين بأنه ليس هناك شر أو خير محض، والهجرة، والتعلم، واصطناع السرور."},{"h":"الحيل الدفاعية","x":"كالتبرير والإسقاط والتعويض والتعميم، «أنها تعمل بطريقة لا شعورية» و«أنها تنكر الواقع وتشوِّهه وتزيِّفه»، ويُستثنى منها التسامي والإعلاء."}]},{"t":"(30) الإنسان كائن مقلد","pg":305,"key":"إن التقليد عبارة عن محاكاة من لا يملك الخبرة لمن يملكها","p":["فأنت لا تستطيع نقل التجارب الحضارية من أمة إلى أمة أو من دولة إلى دولة، وإنما تستطيع أن تستلهم، وتقتبس، وهذا يتطلب منك أقلَمة ما اقتبسته، والأقلَمة عمل إبداعي بامتياز","إنَّ مَنْ يحاول ويخطئ أفضل بكثير ممن يمعن في التقليد"],"items":[{"h":"مقلد بطبعه","x":"«الإنسان بطبعه كائن مقلد، الاجتهاد يغريه بالاجتهاد، والنبل يغريه بالنبل، كما يغريه العدوان بالعدوان»"},{"h":"نتائج غير مضمونة","x":"تقليد أب لصديقه في التربية أو مطعم لآخر في طهيه لا يوصل بالضرورة إلى النتيجة نفسها."},{"h":"سطوة التقاليد","x":"«إن التقاليد الاجتماعية لا تنتشر بسبب أنها تحقِّق مصلحة، أو تدفع مضرَّة، وإنما بسبب نوعية من يتبنَّاها وكثرتهم»"},{"h":"من نقلد","x":"نقلد النبي المعصوم، ثم الناجحين المشهورين بالتوسط، ولا نغتر بالكثرة."},{"h":"أين يكون التقليد مذمومًا","x":"الأصول لا اجتهاد فيها، أما الفروع والطوارئ فهي مناط الإبداع، والتقليد فيها كسل ذهني."},{"h":"التعليم","x":"المطلوب تعليم يقوم على الإبداع وتجريب الطالب ومشاركته لا على التلقين."}]}],"quiz":[{"q":"بم يشبّه المؤلف التذمر من حيث نفعه وضرره؟","o":["بالقلق، قليله نافع وكثيره ضار","بالدواء المر الذي لا بد منه","بالمرض الذي يجب استئصاله سريعًا","بالعادة التي يصعب تغييرها مع الزمن"],"why":"والتذمر من هذه الناحية يشبه ( القلق ) قليلُه نافع، وكثيره ضار.","pg":46},{"q":"موظف مرتشٍ يكثر الشكوى من انتشار الرشوة في مؤسسته. كيف يفسر الكتاب سلوكه؟","o":["وسيلة خفية للتعمية والدفاع عن ذاته","علامة على صحوة ضميره وتوبته الصادقة","ثقافة عامة تلقاها من الكبار في بيئته","نقد موضوعي يقترح الحلول والبدائل"],"why":"وهكذا تصبح الشكوى وسيلة خفية للتعمية والدفاع عن الذات بطريقة غير مباشرة.","pg":49},{"q":"رجل أخفق في حياته الأسرية فاتجه إلى العمل في جمعية خيرية. أي الحيل يعدها المؤلف مستثناة من ذم الحيل الدفاعية وتنطبق على حاله؟","o":["حيلة التسامي والإعلاء","حيلة التبرير والاعتذار","حيلة الإسقاط على الغير","حيلة التعميم على الكل"],"why":"لكن لنا أن نستثني منها حيلة مهمة، وهي حيلة التسامي والإعلاء، وهذه الحيلة يمكن أن نعرِّفها بأنها ارتفاع الإنسان بالسلوك الإنساني غير المقبول إلى سلوك آخر مقبول شخصيًّا واجتماعيًّا","pg":165},{"q":"أي القادمين من البادية إلى المدينة يكون التكيف عليه أسهل في رأي المؤلف؟","o":["المتعلم الثري","الفقير المعدم","الجاهل الفقير","الشاب الطموح وحده"],"why":"فإن المرء كلما كان أقوى عزيمة وأفضل تعليمًا ومتمكنًا ماليًّا أكثر كان التكيف عليه أسهل","pg":161},{"q":"في أي المسائل يكون التقليد مظهرًا من مظاهر الكسل الذهني؟","o":["في الأمور الفرعية والجزئية والطارئة","في الأصول والكليات المجمع عليها كلها","في فرضية الصلاة وبر الوالدين وأمثالها","في اتباع النبي والاقتداء بسنته وهديه"],"why":"أما الأمور الفرعية والجزئية والأمور الطارئة فإنها هي مناط الإبداع والاجتهاد، والتقليدُ فيها مظهر من مظاهر الكسل الذهني وركود الحضارة.","pg":310}],"scene":{"t":"درس قائم على التلقين","x":"معلم يكتفي بأن يحفظ طلابه ما يمليه عليهم ويرددوه، ويلاحظ أنهم لا يحسنون التفكير في مسألة جديدة.","opts":["يجعل تعليمه قائمًا على الإبداع وتجريب الطالب ومشاركته الفاعلة","يزيد كمية المحفوظات ليضمن نجاحهم في الاختبار","يمنع الطلاب من المحاولة حتى لا يخطئوا"],"why":"التعليم في كثير من مدارسنا يقوم على التلقين أي تقليد أفكار ومقولات الملقِّن على حين أن المطلوب اليوم تعليمٌ يقوم على الإبداع وتجريب الطالب ومشاركته الفاعلة، وتحقيق هذا أحد شروط النهوض بالتعليم.","pg":311}},{"k":"c7","t":"الضغوط والظروف الصعبة","q":"ماذا تفعل الضغوط والظروف المتدهورة بالإنسان وخياراته؟","essence":"الضغط يشوه، والظروف السيئة تفسد الموازنات","kw":["الضغط","الموازنات","الضروريات"],"sections":[{"t":"(13) لا موازنات جيدة في ظروف متدهورة","pg":127,"key":"كما أننا حين نكون في ظروف صعبة ومتدهورة فإن كل الموازنات التي نُجرِّبها ستكون رديئة؛ لأننا حينئذ سنوازن بين السيئ والأسوأ","p":["إذا كانت الموازنات مرتبطة بوجود الظروف الملائمة وبوفرة الخيارات المطروحة، فهذا يعني أن العمل الاستراتيجي الذي ينبغي أن يظلَّ محور كثير من أنشطتنا هو تحسين البيئة العامة التي نتحرك فيها"],"items":[{"h":"من أخفض تخير","x":"من كان في رخاء تكون أمامه خيارات كثيرة فيختار ما يحلو له."},{"h":"طالب الفيزياء","x":"شاب موهوب في بلد متخلف تسوء كل خياراته، «فهو كمن يقف في حقل أشواك، حيثما اتجه وجد شيئًا يؤذيه!»"},{"h":"تقدم السن","x":"كلما تقدمنا في السن تراجعت خياراتنا وصعبت موازناتنا."},{"h":"أحلاهما مر","x":"امرأة زوجها مدمن تجد نفسها بين العيش مع الإهانة وطلب الطلاق."},{"h":"كيف نتعامل","x":"نحسن البيئة العامة، ونعمل في التطوع والخير، ونؤجل القرار أمام الخيارات السيئة، ونوازن بهدوء وروية."}]},{"t":"(14) الضغط مصدر تشويه","pg":137,"key":"الضغط هو الحمل الذي يقع على كاهل الكائن الحي كي يقوم بشيء، أو يتخلى عن شيء، أو يتلاءم مع شيء يشعر أنه خارج حدود استطاعته أو مصلحته الحيوية","p":["إن شيئًا من الضغط يشكل دافعًا إيجابيًّا؛ لأنه يُحسِّن من مستوى اليقظة الذاتية","لأن من المعروف أن الضغط في المجال الاجتماعي ينتج عنه في الغالب نفاق في السلوك."],"items":[{"h":"الضغط الاجتماعي","x":"العقل الجمعي ليس راشدًا دائمًا، فيضغط بقيم لا يراها الجيل الجديد مهمة، وآثاره نفسية وجسدية."},{"h":"الضغط الأسري","x":"كأب يلح على ابنه أن يدرس الطب وهو لا يحبه، وقد يظهر الضغط على الطفل في قضم الأظافر والتلعثم."},{"h":"ضغوط الامتحانات","x":"تشوه حياة الطالب، وقد تدفع بعضهم إلى التحايل والغش."},{"h":"ضغط العاطفة","x":"حين نتعلق بشيء نستحث عقولنا على تسويغه، والضغط الطويل يشوه الأفكار."},{"h":"الحزم بلا قسوة","x":"«إن الحكومة الفاضلة هي التي تدير شؤون بلادها بأقل قدر ممكن من القوة، ولا يختلف عنها في شيء أرباب الأسر والمدرسون ورؤساء الشركات ومدراء المصانع»"},{"h":"مقاومة الضغوط الظالمة","x":"خط استراتيجي يغير العلاقة بمصدر الضغط، وخط مباشر بالاحتساب والرياضة والاسترخاء والبوح للأصدقاء."}]},{"t":"(26) الحرمان من الضروريات يدمر الاهتمامات الثقافية العليا","pg":263,"key":"حين يشعر المرء بالعجز عن تأمين قوته الضروري، ويشعر بالعجز عن إيجاد مسكن يؤويه، ويشعر بالخوف الشديد من بطش من حوله وتستمر هذه المشاعر مدة طويلة يكون في الحقيقة بمنأى عن الاهتمام بكلِّ ما يتصل بالثقافة العليا","p":["سيطرة الغرائز على البشر هائلة، وفيها حكمة بالغة؛ لأنها شرط لاستمرار البشر، وفيها أيضًا ابتلاء، فنحن نرتقي على مقدار ما ننجزه من توسيع المساحة بيننا وبين الحيوان"],"items":[{"h":"الإنسان يتحكم بغرائزه","x":"الصائم والشاب الذي يؤخر زواجه والسجين المضرب عن الطعام شواهد على تحكم لا يعرفه الحيوان."},{"h":"هرم الحاجات","x":"يذكر المؤلف هرم ماسلو، وأن الحاجات الأساسية إن لم تُلبَّ ظل الإنسان مشدودًا إليها."},{"h":"الغريزة والوعي","x":"«إن كل من يعطش يبحث عن الماء، ولكن ليس كل من يجهل أمرًا يبحث عن معرفته»"},{"h":"ما يمنعه الحرمان","x":"النظرة الإيجابية، والشعور بالنمو، والحياة الهادفة، والعلاقات الجديدة، والمواهب، والعمل التطوعي."},{"h":"مساران وثلاث جهات","x":"إشباع الغرائز في إطار المباح، وإعلاء الاهتمامات، والأسرة والمدرسة والإعلام مسؤولة عن بناء الحصانة."},{"h":"الطبقة الوسطى والمبدعون","x":"يدعو المؤلف إلى توسيع الطبقة الوسطى، وتكثير طبقة الإبداع بالتحفيز وبث الأمل في المناهج."}]}],"quiz":[{"q":"ما الذي يجعل كل موازناتنا رديئة في الظروف المتدهورة؟","o":["أننا نوازن حينئذ بين السيئ والأسوأ","أننا نفقد القدرة على التفكير تمامًا","أن الآخرين يفرضون علينا قراراتنا","أن الوقت لا يتسع لأي موازنة"],"why":"كما أننا حين نكون في ظروف صعبة ومتدهورة فإن كل الموازنات التي نُجرِّبها ستكون رديئة؛ لأننا حينئذ سنوازن بين السيئ والأسوأ","pg":128},{"q":"طالب أهمل طوال العام ثم حاول حفظ كمية ضخمة في أسابيع قليلة قبل الامتحان. ما الأثر الذي ينبه إليه الكتاب لهذا الضغط؟","o":["القلق وتشويه السلوك وقد يدفع إلى الغش","زيادة الإبداع وحب المادة الدراسية وتعلمها","تقوية الذاكرة على المدى الطويل والقصير","تحسين علاقة الطالب بمعلميه وزملائه"],"why":"أضف إلى هذا أن ضغط الامتحانات دفع بعض الطلاب إلى التحايل والغش","pg":141},{"q":"بم يقيس المؤلف فضل الحكومة، ومثلها رب الأسرة والمدرس؟","o":["إدارة الشؤون بأقل قدر ممكن من القوة","كثرة القوانين وشدة متابعة تنفيذها بدقة","سرعة إيقاع العقاب عند كل مخالفة","الحزم الدائم مع كل تقصير يقع منهم"],"why":"إن الحكومة الفاضلة هي التي تدير شؤون بلادها بأقل قدر ممكن من القوة، ولا يختلف عنها في شيء أرباب الأسر والمدرسون ورؤساء الشركات ومدراء المصانع","pg":143},{"q":"كيف يفسر المؤلف انفضاض الناس إلى القافلة وتركهم النبي قائمًا يخطب؟","o":["الجوع جعل شراء الطعام أمرًا ملحًّا لهم","ضعف إيمانهم وقلة تعلقهم بالدين","جهلهم بحكم صلاة الجمعة وخطبتها","رغبتهم في الربح والتجارة الواسعة السريعة"],"why":"حيث إن الجوع الذي كان في المدينة جعل من محاولة شراء شيء من الطعام الذي كان في القافلة أمرًا مُلحًا لمعظم الناس مما حملهم على الخروج من المسجد قبل فراغه من خطبته","pg":269},{"q":"ما الجهات الثلاث التي يحملها الكتاب مسؤولية صياغة الشخصية وبناء الحصانة الأخلاقية؟","o":["الأسرة والمدرسة والإعلام","الأسرة والمسجد والحكومة","المدرسة والسوق والأصدقاء","الإعلام والجيران والأندية"],"why":"هناك ثلاث جهات مسؤولة عن صياغة الشخصية وتوجيه الاهتمامات وبناء الحصانة الأخلاقية، وهذه الجهات هي الأسرة والمدرسة والإعلام","pg":271}],"scene":{"t":"معلم تحت ضغط ظالم","x":"معلم يتعرض لضغوط عمل متواصلة يراها ظالمة، وبدأ يشعر بالتوتر في بيته وفصله.","opts":["يعمل على تغيير علاقته بمصادر الضغط وتحسين ظروفه، ويخفف عن نفسه بالرياضة والبوح لصديق","يكتم كل شيء ويتحمل حتى لا يظهر ضعفه","ينقل ضغطه إلى طلابه بالقسوة عليهم"],"why":"خط استراتيجي؛ حيث يعمد المرء إلى تغيير علاقته بالأشياء التي تسبب له الضغط وإلى العمل على تحسين ظروفه الشخصية.","pg":144}},{"k":"c8","t":"التحضر وتحولات الحياة","q":"كيف يغير التقدم الحضاري معارفنا ومسؤولياتنا وطابع حياتنا؟","essence":"التحضر يوسع المعارف والمسؤوليات ويُليّن الحياة","kw":["التحضر","المسؤولية","الاجتهاد"],"sections":[{"t":"(4) لا تتسع مرحلة سابقة لمرحلة لاحقة","pg":35,"key":"إنني من خلال تأمل سيرورة الأفكار والنُّظُم والأوضاع والعلاقات وجدت أنها جميعًا تنتقل من الضيق إلى السعة، ومن البساطة إلى التركيب والتعقيد","p":["نحن نحترم جهود السلف، ونعتز بها، لكن علينا أن نميِّز بين جهودهم في فهم النصوص وبين جهودهم في فهم الحياة","فإن من المهم أن نحفِّز كل شاب من الشباب على أن يكون له شيء محدد يهتم به ويتقنه، ويُعرف به."],"items":[{"h":"أسباب الاتساع","x":"انتقال الناس من البادية إلى المدن، والتقنية التي تطور الحياة اليومية، وتراكم المعارف مع الأيام."},{"h":"الاجتهاد الفقهي","x":"«وهذا كله يؤكِّد السُّنة التي نتحدث عنها؛ حيث لا تتسع معارف ونظم ومفاهيم مرحلة سابقة لمرحلة لاحقة.»"},{"h":"التنظيم الإداري","x":"بدأت الدولة في عهد النبوة بأبسط صورها، ثم نشأت الدواوين والعملة وبيت المال."},{"h":"النقد والتجديد","x":"«فالنقد أحد وجهي البناء.»، ونتلقى الجديد بعقول مفتوحة دون أن نقبل كل جديد."},{"h":"التخصص","x":"«انتهى زمان العالم الموسوعي»"}]},{"t":"(10) كلما تقدم الإنسان اتسعت دائرة مسؤولياته","pg":95,"key":"الشعور بالمسؤولية هو شعور المرء بأنه قادر على أن يُلزم نفسه بإنجاز عمل أو وقوف موقف ما، ثُم القدرة على الوفاء بذلك الالتزام بواسطة جهوده الخاصَّة.","p":["التربية إذن هي الأداة التي توسع مساحة الشعور بالمسؤولية","لا ينمو الشعور بالمسؤولية في أجواء القهر والكبت والمتابعة الشديدة، وإنما ينمو في أجواء الحرية"],"items":[{"h":"أفقي ورأسي","x":"«كلكم راع وكلكم مسؤول عن رعيته»، و«ونكتب ما قدموا وآثارهم»، وقول عمر في الشاة التي تعثر بأرض العراق."},{"h":"الوازع الداخلي","x":"الحرية الواسعة في المدن الكبرى تجعل المستقيم يشعر بمسؤوليته عن قراراته."},{"h":"البدائل والمعارف","x":"ابن المدينة يحتار بين بدائل كثيرة في التعليم والعمل والعلاج، فيشعر بمسؤولية الاختيار."},{"h":"معيار للتحضر","x":"اتساع الشعور بالمسؤولية معيار للتحضر، واتساع اللامبالاة ومخالفة الأنظمة مؤشر على التخلف."},{"h":"قاعدة الحرية","x":"« مارس حريتك، وادفع الثمن »، فالتربية والقيادة تعولان على التحفيز والجاذبية لا على الإكراه."},{"h":"وضوح العقود","x":"«وقد دلَّتْ الخبرة التاريخية على أن غموض العقود والاتفاقيات من أكثر ما يتيح للناس التنصُّل من واجباتهم ومسؤولياتهم.»"}]},{"t":"(15) التحضر يكسو الحياة حلة أنثوية","pg":147,"key":"ومن الملاحظ أن الناس كلما مضوا في طريق التحضُّر، وكلما تمكنوا في المدنية أكثر جنحوا نحو المعاني الأنثوية","p":["فأنا في هذه السُّنة لا أهدفُ إلى ترجيح كفَّة النساء على كفَّة الرجال، ولا إلى إعطاء شهادة تزكية لكلِّ أشكال التحضُّر وأوضاعه","كلما درج الناس في طريق التمدن والتحضر صار اهتمامهم بالمظهر أكبر من اهتمامهم بالجوهر"],"items":[{"h":"البساطة والتركيب","x":"البداوة هي الحياة البسيطة الأولى، وحياة المدينة مركبة معقدة، والبسيط يسبق المركب."},{"h":"الاهتمام بالتفاصيل","x":"«لوْ عُدْنا اليوم إلى حياتنا الحضرية لوجدنا أن الاهتمام بالتفاصيل يشكِّل أحد أهم المؤشرات على الرقي الحضاري والتقدم الصناعي»"},{"h":"النعومة واللطف","x":"جزء من نعومة الحياة اليوم سببه انقضاء الحاجة إلى الخشونة، إذ حلت المعرفة محل القوة."},{"h":"حضارة الشكل","x":"الحضارة الحديثة حضارة شكل ومظهر، ويحتاج المرء إلى جهد حتى لا يهمل الجوهر."},{"h":"الاعتدال","x":"اللطف ومراعاة الآخرين مطلوبة شرعًا وذوقًا، مع البعد عن الشطط."}]}],"quiz":[{"q":"ما الذي يدعو المؤلف إلى التمييز بينه في جهود السلف؟","o":["جهودهم في فهم النصوص وجهودهم في فهم الحياة","جهود الصحابة وجهود من جاء بعدهم من العلماء","جهودهم في العبادات وجهودهم في العقائد","جهودهم المكتوبة وجهودهم المنقولة شفاهًا"],"why":"نحن نحترم جهود السلف، ونعتز بها، لكن علينا أن نميِّز بين جهودهم في فهم النصوص وبين جهودهم في فهم الحياة","pg":40},{"q":"يرى المؤلف أن الأفكار والنظم تنتقل عبر الزمن في اتجاه معين. ما هو؟","o":["من الضيق إلى السعة ومن البساطة إلى التعقيد","من التعقيد إلى البساطة ومن السعة إلى الضيق","من الكمال إلى النقص كلما مر الزمن","من الثبات المطلق إلى الفوضى الشاملة"],"why":"إنني من خلال تأمل سيرورة الأفكار والنُّظُم والأوضاع والعلاقات وجدت أنها جميعًا تنتقل من الضيق إلى السعة، ومن البساطة إلى التركيب والتعقيد","pg":36},{"q":"أب يريد أن ينمي في أبنائه الشعور بالمسؤولية. في أي الأجواء ينمو هذا الشعور بحسب الكتاب؟","o":["في أجواء الحرية التي يُخيَّر فيها المرء","في أجواء المتابعة الشديدة والمراقبة الدائمة","في أجواء الكبت حتى يعتاد الالتزام","في أجواء القهر التي تمنع وقوع أي خطأ"],"why":"لا ينمو الشعور بالمسؤولية في أجواء القهر والكبت والمتابعة الشديدة، وإنما ينمو في أجواء الحرية","pg":103},{"q":"لماذا يكون الوازع الداخلي لدى المستقيم من أبناء المدن الكبرى أقوى في رأي المؤلف؟","o":["لأن الحرية الواسعة تُشعره بمسؤوليته عن قراراته","لأن رقابة الآخرين عليه في المدينة أشد وأقسى","لأن عقوبات المدن أقسى من عقوبات البادية","لأنه أكثر تدينًا من ابن البادية بطبعه وفطرته"],"why":"وهذه المساحة الواسعة من الحرية تجعله يشعر بمسؤولياته عن القرارات التي سيتخذها في ممارسة ذلك العدد الكبير من الأنشطة والسلوكيات التي أتيحت له","pg":99},{"q":"ما الذي يعده المؤلف من أهم مؤشرات الرقي الحضاري والتقدم الصناعي؟","o":["الاهتمام بالتفاصيل","كثرة المباني الشاهقة","وفرة الثروات الطبيعية","اتساع المدن وسكانها"],"why":"لوْ عُدْنا اليوم إلى حياتنا الحضرية لوجدنا أن الاهتمام بالتفاصيل يشكِّل أحد أهم المؤشرات على الرقي الحضاري والتقدم الصناعي","pg":150}],"scene":{"t":"طلاب يهابون التطوع","x":"معلم يريد أن يغرس في طلابه الشعور بالمسؤولية الاجتماعية، لكنهم يترددون في المشاركة في أي مبادرة.","opts":["يزجهم في مبادرة عملية صغيرة ويشجعهم على كسر رهبة البداية","يكتفي بمحاضرة طويلة عن فضل التطوع","يفرض المشاركة بالدرجات والعقوبة"],"why":"لكن نحتاج إلى ما يكفي من العزيمة كي نكسر رهبة الخطوة الأولى.","pg":104}},{"k":"c9","t":"القيم والمصالح","q":"كيف تتجاذب القيم والمصالح سلوك الإنسان؟","essence":"القيم تجمع، والمصالح تفرق، والوعي يوازن بينهما","kw":["القيم","المصالح","التضحية"],"sections":[{"t":"(18) القيم تجمع والمصالح تفرق","pg":179,"key":"إن المرء إذا أراد أن يحقق الحد الأقصى من مصالحه الخاصَّة مع التمسك بالقيم والمبادئ التي يؤمن بها، فإنه في الحقيقة يحاول الجمع بين نقيضين","p":["إن القيم هي المصالح الجماعية في مقابل المصالح الفردية","إن عظمة أي مجتمع تتجلَّى في حجم الشريحة الفاضلة القادرة على التضحية ببعض مصالحها من أجل المصلحة العامَّة"],"items":[{"h":"القيم والمصالح","x":"القيم كل ما نقدره ونجله من معان وأشياء وسلوكيات، والمصالح «كلُّ ما يظن الإنسان أنه يحقق له نفعًا، أو يدفع عنه ضرًّا»."},{"h":"المصالح ليست شرًّا","x":"الحديث عن المصالح بوشاح السلبية مثالية، والمذموم منها ما يُنال بطرق غير مشروعة."},{"h":"الشياطين في التفاصيل","x":"ولي اليتيم يقسو عليه ويزعم أنه يرحمه، فتُنتهك القيم مع ادعاء احترامها."},{"h":"لماذا تجمع القيم","x":"لأنها تحقق الألفة، ولأنها عالمية، ولأنها خبرة بشرية موروثة، ولأن الإنسان مفتقر إلى المجتمع."},{"h":"الافتراق الجميل","x":"من حق كل إنسان أن يحدد مصالحه، وإذا افترق الناس «فالافتراق يمكن أن يكون ناعمًا ولطيفًا، وهذا هو الذي يفعله الكرام والنبلاء»"}]},{"t":"(29) التقدم الحضاري وعي أشد بالمصالح","pg":297,"key":"في إمكاننا تعريف التقدُّم الحضاري بأنه ذلك الارتقاء في الأفكار والأذواق والعلاقات مصحوبًا بكثير من النظم والمؤسسات والأدوات مع الكثير من أشكال الترفيه والكثير من البدائل والخيارات","p":["إذن التقدُّم الحضاري لا يجعل الناس أكثر تديُّنًا، وإنما يتيح لهم من الوعي ما يساعدهم على أن يعيشوا حياتهم مع العمل لآخرتهم إن أحبوا."],"items":[{"h":"اتساع دائرة المصالح","x":"التقدم الحضاري لا يجعل الوعي بالمصالح أشد فحسب، بل يوسع دائرتها كذلك."},{"h":"الوعي الصحي","x":"كلما ارتقى الناس في سلم الحضارة تحسن إدراكهم لمصالحهم الصحية."},{"h":"المصالح تزاحم المبادئ","x":"الانغماس في المرفهات يجعل كثيرًا من الناس ينسون مبادئهم في سبيل مصالحهم."},{"h":"في إطار الواجبات","x":"نخدم مصالحنا في إطار واجباتنا ومبادئنا، «وذلك لأن صوت المصالح يُسمع دائمًا على نحو أوضح من صوت المبادئ.»"},{"h":"المصلحة الكبرى","x":"نستهدف دائمًا الفوز برضوان الله، ونخدم الضعفاء، ونفرق بين المصلحة الحقيقية والمتوهمة."}]}],"quiz":[{"q":"لماذا يُجمع الناس على قيم كالعدل والأمانة والرحمة؟","o":["لأنها تحقق مصلحة اجتماعية عامة","لأنها تخدم مصالحهم الشخصية مباشرة","لأن القانون يفرضها بالعقوبة","لأنها موروثة لا يُسأل عن سببها"],"why":"هذه القيم لا تتحقق إلا من خلال تواصل الناس واجتماعهم، ويمكنك أن تقول: إنها تحقق مصلحة اجتماعية، ولهذا فإن من الطبيعي أن يُجمع عليها الناس","pg":181},{"q":"صديقان شريكان قررا فض شراكتهما لاختلاف مصالحهما. بم يوصي الكتاب في مثل هذا الحال؟","o":["أن يكون الافتراق ناعمًا لطيفًا دون عداوة","أن يتمسك كل منهما بحقه كاملًا حتى النهاية","أن يقطع كل منهما صلته بالآخر تمامًا وإلى الأبد","أن يحتكما إلى الناس ليعرفوا المخطئ منهما"],"why":"فالافتراق يمكن أن يكون ناعمًا ولطيفًا، وهذا هو الذي يفعله الكرام والنبلاء","pg":185},{"q":"بم تتجلى عظمة أي مجتمع في رأي المؤلف؟","o":["حجم الفئة القادرة على التضحية للصالح العام","كثرة ثرواته وقوة اقتصاده بين الأمم","عدد علمائه ومثقفيه ومؤلفاته الكثيرة المنتشرة","اتساع أرضه وكثرة سكانه وقوة جيوشه"],"why":"إن عظمة أي مجتمع تتجلَّى في حجم الشريحة الفاضلة القادرة على التضحية ببعض مصالحها من أجل المصلحة العامَّة","pg":186},{"q":"هل يجعل التقدم الحضاري الناس أكثر تدينًا بحسب الكتاب؟","o":["لا، لكنه يمنحهم وعيًا يعين على العمل للآخرة","نعم، لأن العلم يقود دائمًا إلى الإيمان بالله","لا، لأنه يقود حتمًا إلى ترك الدين وتعاليمه","نعم، لأن الرفاهية تفرغ الناس للعبادة والذكر"],"why":"إذن التقدُّم الحضاري لا يجعل الناس أكثر تديُّنًا، وإنما يتيح لهم من الوعي ما يساعدهم على أن يعيشوا حياتهم مع العمل لآخرتهم إن أحبوا.","pg":300},{"q":"لماذا يدعو المؤلف إلى خدمة مصالحنا في إطار واجباتنا ومبادئنا؟","o":["لأن صوت المصالح يُسمع أوضح من صوت المبادئ","لأن المصالح كلها مذمومة في نظر الشرع والعقل","لأن المبادئ تكفي وحدها لتوجيه السلوك","لأن المصالح لا تتغير بتغير الحضارة"],"why":"وذلك لأن صوت المصالح يُسمع دائمًا على نحو أوضح من صوت المبادئ.","pg":301}]},{"k":"c10","t":"الوحدة والتماسك والهوية","q":"ما الذي يحفظ وحدة المجتمع وما الذي يصدعها؟","essence":"الوحدة جهد متجدد، والتصلب يصدعها، والهوية تحتاج توازنًا","kw":["الوحدة","المرونة","الهوية"],"sections":[{"t":"(21) التخلف يحطم الوحدة","pg":209,"key":"وحدة المجتمع ليست شيئًا يتمُّ إيجاده، ويخلد بعده الناس إلى الراحة، إنها مشروع تحت الإنجاز","p":["لا ريب عندي في أن الأصل هو الانكفاء على الذات والعيش في مجموعات صغيرة يجمع بينها قدر يسير من القواسم المشتركة","إن التصدع في الأمم والجماعات والتيارات يشبه وحشًا كامنًا ينتظر الفرصة حتى ينقضَّ على فريسته، والذي يحول بينه وبين ذلك هو كثرة القواسم المشتركة"],"items":[{"h":"ثمن الوحدة","x":"للوحدة ثمن من تقييد الحرية والتنازل عن بعض الخصوصيات، فيقع صراع خفي بين الرغبة فيها والخوف منها."},{"h":"معنى الانحطاط","x":"«إن الانحطاط هو تخلف روحي وأخلاقي ومادي شديد عن النماذج الحضارية والمدنية السائدة في عصر من العصور»"},{"h":"الفكرة قبل الواقع","x":"الوحدة الأوربية تبلورت أولًا في أذهان المفكرين والفلاسفة ثم جاءها الدعم."},{"h":"الوطن الجاذب","x":"يحتاج الوطن إلى الأمن والعدل وتكافؤ الفرص والتقارب الطبقي ليبقى القاسم المشترك الأعظم."},{"h":"كيف نتعامل","x":"نؤمن بأن الأمور إذا تُركت على عواهنها كان الانقسام، ونقاوم العنصرية والطائفية، ونعمل بتدرج صبور، ونتسامح مع الاختلاف."}]},{"t":"(23) التصدع موصول بالتصلب","pg":229,"key":"الليونة ليست هي الذوبان والميوعة، والاستسلام، وإنما هي مرونة في صلابة","p":["« لا تكن يابسًا فتُكسر، ولا تكن لينًا فتُعصَر »","إن في إمكاننا أن نقول: إن المرونة هي أساس التكيف، فلا تكيف من غير مرونة، كما أنه لا حياة ولا استمرار من غير تكيف"],"items":[{"h":"الجماعات المتشددة","x":"الأحزاب والجماعات الأكثر تطرفًا وتشددًا هي الأكثر تصدعًا، ومن هنا قيل: «الثورة تأكل أبناءها»."},{"h":"مظاهر التصلب الفكري","x":"الحدية في التفكير، والتفكير بأطر قديمة، والتعصب، والإيمان بالخرافات."},{"h":"قول الشافعي","x":"« مذهبنا صواب يحتمل الخطأ، ومذهب غيرنا خطأ يحتمل الصواب »"},{"h":"الحوار والطلاق","x":"«أن تُري محاورك نقطة لا يراها، وأن يُريك محاورك نقطة لا تراها»، والانسحاب من الحوار من أسباب الطلاق."},{"h":"الصلح","x":"«والصلح هو عقد يرفع النزاع، ويقطع الخصومة بين المتصالحين»"},{"h":"حديد الزهر","x":"شديد الصلابة لكنه هش وأكثر قابلية للكسر من أنواع الحديد الأخرى."}]},{"t":"(25) انتعاش التعددية لا يكون إلا على حساب الهوية","pg":251,"key":"والعلاقة بين ( التعددية ) و( الهُويَّة ) هي علاقة نفي؛ حيث تنكمش مدلولات ( الهُويَّة ) وتجسيداتها حين يتسامح الناس تجاه ( التعددية )","p":["والهُويَّة الثقافية لأي شعب من الشعوب هي ذلك القدر الثابت والجوهري والمشترك من السمات والقسمات العامَّة التي تميِّز حضارته عن غيرها من الحضارات.","إذا رأيت الناس يبحثون عن ملامح هُويَّتهم ومحدداتها، فاعلم أنهم صاروا يشعرون بأنها مُهدَّدة، فالهُويَّة مثل الصحة لا نشعر بها إلا إذا كانت على غير ما يرام."],"items":[{"h":"ثوابت ومتغيرات","x":"في كل هوية عناصر ثابتة وأخرى قابلة للتحول، وهذا ما يساعدها على التكيف والاستمرار."},{"h":"ثوابت الهوية الإسلامية","x":"أركان الإيمان والإسلام، والدنيا دار ابتلاء، وأخوة المسلمين، والانتماء إلى التاريخ الإسلامي، وحب العربية، والأعراف الصالحة."},{"h":"التقدم والتعددية","x":"«إن التقدم الحضاري والعمراني لا يعمل لصالح تعزيز الهُويَّات، وإنما يعمل لصالح ( التعددية )»"},{"h":"الأجزاء الصلبة","x":"الأنجع من البكاء على الهوية تحديد أجزائها الصلبة وتوفير البيئات التي تساعد على حضورها."},{"h":"الأقليات","x":"حين تخاف الأقليات على هوياتها تزداد تمسكًا بها، فعلى الأكثرية أن ترسل إليها رسائل الطمأنة."}]}],"quiz":[{"q":"ما الأصل في حياة البشر بين التوحد والتفرق في رأي المؤلف؟","o":["الانكفاء والعيش في مجموعات صغيرة","التوحد والانخراط في كيانات كبيرة","التوحد في البداوة والتفرق في المدن","التوازن التام بين التوحد والتفرق"],"why":"لا ريب عندي في أن الأصل هو الانكفاء على الذات والعيش في مجموعات صغيرة يجمع بينها قدر يسير من القواسم المشتركة","pg":210},{"q":"ما المرونة المحمودة كما يصفها الكتاب؟","o":["مرونة في صلابة لا ذوبان فيها ولا ميوعة","الاستسلام لرأي الآخرين تجنبًا للخلاف معهم","التخلي عن الثوابت مواكبة للعصر وأهله","التصلب في الفروع والليونة في الأصول"],"why":"الليونة ليست هي الذوبان والميوعة، والاستسلام، وإنما هي مرونة في صلابة","pg":230},{"q":"زوجان كلما اختلفا أعرض أحدهما عن النقاش ولزم الصمت. ما الذي ينبه إليه الكتاب في ذلك؟","o":["الانسحاب من الحوار من أهم أسباب الطلاق","الانسحاب يحفظ الود ويمنع تفاقم الخلاف","الانسحاب علامة على قوة الشخصية","الانسحاب لا يضر ما دام الاحترام قائمًا"],"why":"وقد دلَّتْ إحدى الدراسات على أن انسحاب أحد الزوجين أو كليهما من الحوار يُعدُّ واحدًا من أهم الأسباب المؤدِّية إلى الطلاق","pg":234},{"q":"إذا رأيت الناس يبحثون بإلحاح عن ملامح هويتهم، فعلام يدل ذلك في رأي المؤلف؟","o":["أنهم يشعرون بأنها مهددة","أنهم بلغوا قمة الوعي الحضاري","أنهم يريدون التخلي عنها","أنهم يسعون إلى التعددية"],"why":"إذا رأيت الناس يبحثون عن ملامح هُويَّتهم ومحدداتها، فاعلم أنهم صاروا يشعرون بأنها مُهدَّدة","pg":254},{"q":"لماذا لم يحمل الإسلام الشعوب التي دخلت فيه على ترك لغاتها، ولم يحدد لها أشكال الملابس؟","o":["لأنه أقام توازنًا دقيقًا بين الفرد والجماعة","لأنه لم يهتم بشؤون الثقافة والعادات والتقاليد","لأن تلك الشعوب رفضت التخلي عنها رفضًا شديدًا","لأن العربية لم تكن قد انتشرت بينهم بعد"],"why":"الإسلام أقام توازنًا دقيقًا بين الفرد والجماعة، وهذا اقتضى توسيع مساحات الابتكار والتجديد الاجتماعي، وهو بدوره يقتضي عدم توسيع دوائر الهُويَّة","pg":259}]}],"highlights":[{"x":"فالشيء كثيرًا ما يكون ابن علاقاته.","pg":28},{"x":"فالنقد أحد وجهي البناء.","pg":41},{"x":"انتهى زمان العالم الموسوعي","pg":41},{"x":"أنت لا تستطيع الحصول على حلول كاملة في وسط غير كامل","pg":50},{"x":"الاعتقاد بنسبية نجاحاتنا يحمينا من الغرور والكبر","pg":113},{"x":"إن فقدان الوظيفة هو فقدان للذات أو فقدان للوجود","pg":118},{"x":"المقارنة أُمُّها الاختلاف، وأبوها الغموض","pg":190},{"x":"وحدة المجتمع ليست شيئًا يتمُّ إيجاده، ويخلد بعده الناس إلى الراحة، إنها مشروع تحت الإنجاز","pg":212},{"x":"الليونة ليست هي الذوبان والميوعة، والاستسلام، وإنما هي مرونة في صلابة","pg":230},{"x":"فالهُويَّة مثل الصحة لا نشعر بها إلا إذا كانت على غير ما يرام.","pg":254},{"x":"إنَّ مَنْ يحاول ويخطئ أفضل بكثير ممن يمعن في التقليد","pg":311}],"concepts":[{"term":"السنّة","def":"أما السُّنَّة فإنها ليست شيئًا نصوغه أو نركِّبه، وإنما شيء نكتشفه، ثم نخضع له، أو نتكيف معه.","pg":314},{"term":"التذمر","def":"التذمر عبارة عن انزعاج داخلي بسبب شعور الإنسان بوجود تصرفات أو أشياء لا تُرضيه","pg":45},{"term":"الموقف المتوازن","def":"الموقف المتوازن هو ذلك الموقف الذي يدرك فيه الإنسان على نحوٍ جيد أهدافه وحاجاته وواجباته وإمكاناته والظروف المحيطة به، والمعوقات والعقبات التي قد تواجهه","pg":65},{"term":"الشعور بالمسؤولية","def":"الشعور بالمسؤولية هو شعور المرء بأنه قادر على أن يُلزم نفسه بإنجاز عمل أو وقوف موقف ما، ثُم القدرة على الوفاء بذلك الالتزام بواسطة جهوده الخاصَّة.","pg":96},{"term":"الضغط","def":"الضغط هو الحمل الذي يقع على كاهل الكائن الحي كي يقوم بشيء، أو يتخلى عن شيء، أو يتلاءم مع شيء يشعر أنه خارج حدود استطاعته أو مصلحته الحيوية","pg":137},{"term":"التكيف","def":"التكيف هو عملية مواءمة الإنسان لنفسه مع الأوضاع والظروف الجديدة","pg":157},{"term":"التسامي والإعلاء","def":"ارتفاع الإنسان بالسلوك الإنساني غير المقبول إلى سلوك آخر مقبول شخصيًّا واجتماعيًّا","pg":165},{"term":"النظام","def":"إنه ذلك المجموع الذي يعمل في الوجود بوصفه شيئًا كليًّا مكونًا من أجزاء تتبادل فيما بينها الاعتماد والتفاعل","pg":170},{"term":"القيم","def":"المقصود بالقيم كل تلك المعاني والأشياء والسلوكيات التي نقدِّرها، وننظر إليها باحترام وإجلال","pg":180},{"term":"المصالح","def":"أما المصالح فهي كلُّ ما يظن الإنسان أنه يحقق له نفعًا، أو يدفع عنه ضرًّا","pg":180},{"term":"الانحطاط","def":"إن الانحطاط هو تخلف روحي وأخلاقي ومادي شديد عن النماذج الحضارية والمدنية السائدة في عصر من العصور","pg":210},{"term":"الصلح","def":"والصلح هو عقد يرفع النزاع، ويقطع الخصومة بين المتصالحين","pg":234},{"term":"الجهل المركب","def":"والجهل المركب أن لا يعرف أنه لا يعرف","pg":241},{"term":"الهوية الثقافية","def":"والهُويَّة الثقافية لأي شعب من الشعوب هي ذلك القدر الثابت والجوهري والمشترك من السمات والقسمات العامَّة التي تميِّز حضارته عن غيرها من الحضارات.","pg":252},{"term":"الغرائز","def":"الغرائز قوى بيولوجية داخلية تدفع المرء إلى السلوك بطريقة معينة","pg":264},{"term":"التقدم الحضاري","def":"ذلك الارتقاء في الأفكار والأذواق والعلاقات مصحوبًا بكثير من النظم والمؤسسات والأدوات مع الكثير من أشكال الترفيه والكثير من البدائل والخيارات","pg":297},{"term":"التقليد","def":"إن التقليد عبارة عن محاكاة من لا يملك الخبرة لمن يملكها","pg":306}],"links":[{"topic":"التربية والتهديد والعقاب","pg":79},{"topic":"المسؤولية والحرية","pg":95},{"topic":"العمل التطوعي","pg":101},{"topic":"ضغوط الامتحانات والغش","pg":141},{"topic":"المقارنة بين الأبناء","pg":195},{"topic":"التطرف والاعتدال","pg":199},{"topic":"الحوار والخلاف الزوجي","pg":234},{"topic":"الهوية والتعددية","pg":251},{"topic":"العدل","pg":279},{"topic":"التلقين والإبداع في التعليم","pg":311}]};
